<script>const product=document.getElementById('product'),size=document.getElementById('size');function sizes(){if(!product||!size)return;let first=null;[...size.options].forEach(o=>{o.hidden=o.dataset.product!==product.value;if(!o.hidden&&!first)first=o});if(size.selectedOptions[0]?.hidden&&first)first.selected=true}product?.addEventListener('change',sizes);sizes();</script>
